<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\{BulkTrips,Support};
class DriverTripController extends Controller {
 private function driver():int{abort_unless(auth()->user()->role==='rider'&&auth()->user()->courier_type==='driver',403);return auth()->id();}
 public static function manifest($trip,?int $center=null):array{
  $stops=DB::table('driver_trip_stops as s')->join('sorting_centers as c','c.id','=','s.center_id')->where('s.trip_id',$trip->id)->when($center,fn($q)=>$q->where('s.center_id',$center))->orderBy('s.position')->select('s.*','c.name','c.city','c.province')->get();
  $out=[];foreach($stops as $stop){$items=DB::table('driver_trip_items as i')->join('parcels as p','p.id','=','i.parcel_id')->where('i.stop_id',$stop->id)->select('i.id','i.parcel_id','i.received_at','i.received_by','p.tracking_code','p.status','p.order_id')->get();$centerRecord=DB::table('sorting_centers')->find($stop->center_id);$address=\App\Services\Municipalities::address($centerRecord->user_id);$out[]=['address'=>$address?(object)array_intersect_key((array)$address,array_flip(['recipient','phone','street','barangay','city','province','postal_code'])):null,'id'=>$stop->id,'center_id'=>$stop->center_id,'position'=>$stop->position,'center_name'=>$stop->name,'city'=>$stop->city,'province'=>$stop->province,'handed_over_name'=>$stop->handed_over_by?DB::table('users')->where('id',$stop->handed_over_by)->value('name'):null,'received_by_name'=>$stop->received_by?DB::table('users')->where('id',$stop->received_by)->value('name'):null,'handed_over_at'=>$stop->handed_over_at,'handed_over_by'=>$stop->handed_over_by,'received_by'=>$stop->received_by,'received_at'=>$stop->received_at,'parcels'=>$items];}
  return ['id'=>$trip->id,'status'=>$trip->status,'driver_id'=>$trip->driver_id,'origin_center_id'=>$trip->origin_center_id,'expires_at'=>$trip->expires_at,'accepted_at'=>$trip->accepted_at,'departed_at'=>$trip->departed_at,'completed_at'=>$trip->completed_at,'completed_earnings'=>(float)DB::table('assignments')->where('trip_id',$trip->id)->where('status','completed')->sum('earnings'),'stops'=>$out];
 }
 public function index(Request $r){$driver=$this->driver();BulkTrips::refresh();$tab=$r->input('tab','new');abort_unless(in_array($tab,['new','progress','completed']),422);$states=match($tab){'new'=>['offered'],'progress'=>['accepted','in_transit'],default=>['completed']};$rows=DB::table('driver_trips')->where('driver_id',$driver)->whereIn('status',$states)->orderByDesc('id')->paginate(12)->withQueryString();$trips=$rows->getCollection()->map(fn($t)=>self::manifest($t));
  return $r->expectsJson()?response()->json(['data'=>$trips,'current_page'=>$rows->currentPage(),'last_page'=>$rows->lastPage()]):view('driver_trips',['links'=>app(CommonController::class)->links(),'trips'=>$trips,'page'=>$rows,'tab'=>$tab]);
 }
 public function show(Request $r,int $id){$driver=$this->driver();BulkTrips::refresh($id);$t=DB::table('driver_trips')->where('id',$id)->where('driver_id',$driver)->first();abort_unless($t,404);return response()->json(self::manifest($t));}
 public function history(){abort_unless(auth()->user()->role==='sorting_center',403);$center=DB::table('sorting_centers')->where('user_id',auth()->id())->value('id');abort_unless($center,403);BulkTrips::refresh();$rows=DB::table('driver_trips')->where('origin_center_id',$center)->whereIn('status',['completed','declined','expired','cancelled'])->orderByDesc('id')->paginate(12);return view('center_trip_history',['links'=>app(CommonController::class)->links(),'trips'=>$rows->getCollection()->map(fn($t)=>self::manifest($t)),'page'=>$rows]);}
 public function create(Request $r){abort_unless(auth()->user()->role==='sorting_center',403);$v=$r->validate(['driver_id'=>'required|integer','parcel_ids'=>'required|array|min:1|max:100','parcel_ids.*'=>'required|integer|distinct']);$id=Support::once($r,'bulk-trip',fn()=>BulkTrips::create(auth()->id(),$v['driver_id'],$v['parcel_ids']));return redirect('/ops/transfers')->with('success',"Bulk trip #{$id} offered. Driver accepts the whole trip once.");}
 private function done(Request $r,string $message,string $tab='progress'){return $r->expectsJson()?response()->json(['message'=>$message]):redirect('/driver/trips?tab='.$tab)->with('success',$message);}
 public function accept(Request $r,int $id){BulkTrips::accept($id,$this->driver());return $this->done($r,'Trip accepted. All its parcels are included.');}
 public function decline(Request $r,int $id){BulkTrips::close($id,$this->driver(),'declined');return $this->done($r,'Trip declined. Parcels returned to the origin queue.','new');}
 public function depart(Request $r,int $id){BulkTrips::depart($id,$this->driver());return $this->done($r,'Transport started for every parcel in this trip.');}
 public function handover(Request $r,int $id){$r->validate(['confirm_handover'=>'accepted']);BulkTrips::handover($id,$this->driver());return $this->done($r,'Handover recorded. The destination center must now confirm receipt.');}
 public function cancel(Request $r,int $id){BulkTrips::close($id,auth()->id(),'cancelled');return back()->with('success','Unaccepted trip cancelled. Its parcels can be reassigned.');}
 public function receive(Request $r,int $id){$v=$r->validate(['confirm_receipt'=>'accepted','parcel_ids'=>'required|array|min:1|max:100','parcel_ids.*'=>'required|integer|distinct']);BulkTrips::receive($id,auth()->id(),$v['parcel_ids']);return $r->expectsJson()?response()->json(['message'=>'Selected parcels received.']):redirect('/ops/transfers')->with('success','Selected parcels received. Open Deliveries to assign local riders.');}
}
